CREATE OR REPLACE FUNCTION digest.team_sql(p_sql text, p_max_rows integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'digest', 'event', 'pg_temp'
AS $function$
declare
